//! Small, persistent waveform previews generated by the selected local FFmpeg.
use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize};
use std::{
    fs,
    io::Read,
    path::Path,
    process::{Command, Stdio},
    sync::atomic::{AtomicBool, Ordering},
    time::UNIX_EPOCH,
};

const SAMPLE_RATE: u32 = 2_000;
const MAX_PEAKS: usize = 18_000;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Waveform {
    pub duration: f64,
    pub peaks: Vec<f32>,
}

#[derive(Serialize, Deserialize)]
struct Cache {
    version: u32,
    source_bytes: u64,
    source_modified_ms: u128,
    waveform: Waveform,
}

pub fn load(
    ffmpeg: &Path,
    source: &Path,
    duration: f64,
    cache_file: &Path,
    cancel: &AtomicBool,
) -> Result<Waveform> {
    ensure!(
        duration.is_finite() && duration > 0.,
        "Invalid audio duration"
    );
    let source = source.canonicalize().context("Audio file unavailable")?;
    ensure!(source.is_file(), "Audio file unavailable");
    let metadata = source.metadata()?;
    let modified = metadata.modified()?.duration_since(UNIX_EPOCH)?.as_millis();
    if let Ok(bytes) = fs::read(cache_file)
        && let Ok(cache) = serde_json::from_slice::<Cache>(&bytes)
        && cache.version == 1
        && cache.source_bytes == metadata.len()
        && cache.source_modified_ms == modified
        && valid(&cache.waveform, duration)
    {
        return Ok(cache.waveform);
    }
    ensure!(!cancel.load(Ordering::Relaxed), "Waveform cancelled");

    let mut command = Command::new(ffmpeg);
    command
        .args([
            "-hide_banner",
            "-loglevel",
            "error",
            "-nostdin",
            "-protocol_whitelist",
            "file,pipe",
            "-threads",
            "1",
            "-i",
        ])
        .arg(&source)
        .args([
            "-map",
            "0:a:0",
            "-vn",
            "-sn",
            "-dn",
            "-filter_threads",
            "1",
            "-ar",
            "2000",
            "-ac",
            "1",
            "-f",
            "f32le",
            "pipe:1",
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        command.creation_flags(0x08000000);
    }
    let mut child = command
        .spawn()
        .context("Waveform needs local FFmpeg; select it under Models / Local programs")?;
    let mut stdout = child.stdout.take().unwrap();
    let mut stderr = child.stderr.take().unwrap();
    let log = std::thread::Builder::new()
        .name("laut-waveform-log".into())
        .spawn(move || {
            let mut tail = Vec::new();
            let mut bytes = [0_u8; 2048];
            while let Ok(count) = stderr.read(&mut bytes) {
                if count == 0 {
                    break;
                }
                tail.extend_from_slice(&bytes[..count]);
                if tail.len() > 8192 {
                    tail.drain(..tail.len() - 8192);
                }
            }
            String::from_utf8_lossy(&tail).trim().to_owned()
        })?;
    let bucket_samples =
        ((duration * f64::from(SAMPLE_RATE) / MAX_PEAKS as f64).ceil() as usize).max(1);
    let mut peaks = Vec::with_capacity(MAX_PEAKS);
    let mut peak = 0_f32;
    let mut in_bucket = 0;
    let mut remainder = Vec::with_capacity(3);
    let mut buffer = [0_u8; 32 * 1024];
    loop {
        if cancel.load(Ordering::Relaxed) {
            let _ = child.kill();
            let _ = child.wait();
            anyhow::bail!("Waveform cancelled");
        }
        let count = stdout.read(&mut buffer)?;
        if count == 0 {
            break;
        }
        remainder.extend_from_slice(&buffer[..count]);
        let complete = remainder.len() / 4 * 4;
        for bytes in remainder[..complete].as_chunks::<4>().0 {
            let sample = f32::from_le_bytes(*bytes);
            if sample.is_finite() {
                peak = peak.max(sample.abs().min(1.));
            }
            in_bucket += 1;
            if in_bucket == bucket_samples {
                peaks.push(peak);
                peak = 0.;
                in_bucket = 0;
            }
        }
        remainder.drain(..complete);
    }
    let status = child.wait()?;
    let log = log.join().unwrap_or_default();
    ensure!(status.success(), "FFmpeg waveform failed: {}", log);
    ensure!(remainder.is_empty(), "Truncated waveform PCM");
    if in_bucket > 0 {
        peaks.push(peak);
    }
    let waveform = Waveform { duration, peaks };
    ensure!(
        valid(&waveform, duration),
        "No usable audio samples for waveform"
    );
    if !cancel.load(Ordering::Relaxed) {
        if let Some(parent) = cache_file.parent() {
            fs::create_dir_all(parent)?;
        }
        let cache = Cache {
            version: 1,
            source_bytes: metadata.len(),
            source_modified_ms: modified,
            waveform: waveform.clone(),
        };
        let temporary = cache_file.with_extension(format!("tmp-{}", std::process::id()));
        fs::write(&temporary, serde_json::to_vec(&cache)?)?;
        // std::fs::rename does not replace an existing destination on Windows.
        // The cache is derived data and this worker is serialized by the UI, so remove only
        // the validated, app-owned destination immediately before publishing its replacement.
        #[cfg(windows)]
        if cache_file.is_file() {
            fs::remove_file(cache_file)?;
        }
        if let Err(error) = fs::rename(&temporary, cache_file) {
            let _ = fs::remove_file(&temporary);
            return Err(error.into());
        }
    }
    Ok(waveform)
}

fn valid(waveform: &Waveform, duration: f64) -> bool {
    waveform.duration.is_finite()
        && (waveform.duration - duration).abs() < 0.05
        && !waveform.peaks.is_empty()
        && waveform.peaks.len() <= MAX_PEAKS + 1
        && waveform
            .peaks
            .iter()
            .all(|p| p.is_finite() && *p >= 0. && *p <= 1.)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    #[test]
    fn cache_validation_rejects_wrong_duration_empty_and_invalid_peaks() {
        assert!(valid(
            &Waveform {
                duration: 10.,
                peaks: vec![0., 0.5, 1.]
            },
            10.
        ));
        assert!(!valid(
            &Waveform {
                duration: 10.,
                peaks: vec![]
            },
            10.
        ));
        assert!(!valid(
            &Waveform {
                duration: 11.,
                peaks: vec![0.5]
            },
            10.
        ));
        assert!(!valid(
            &Waveform {
                duration: 10.,
                peaks: vec![f32::NAN]
            },
            10.
        ));
        assert!(!valid(
            &Waveform {
                duration: 10.,
                peaks: vec![1.1]
            },
            10.
        ));
    }

    #[test]
    #[ignore = "requires LAUT_TEST_FFMPEG; offline codec test, no audio device"]
    fn real_ffmpeg_waveform_is_bounded_cached_and_invalidated_by_audio_changes() {
        let ffmpeg = std::env::var_os("LAUT_TEST_FFMPEG").expect("Set LAUT_TEST_FFMPEG");
        let temp = tempfile::tempdir().unwrap();
        let source = temp.path().join("Sprache ü.wav");
        let cache = temp.path().join("cache/waveform.json");
        let sample_rate = 8_000_u32;
        let mut file = fs::File::create(&source).unwrap();
        let samples = sample_rate * 2;
        file.write_all(b"RIFF").unwrap();
        file.write_all(&(36 + samples * 2).to_le_bytes()).unwrap();
        file.write_all(b"WAVEfmt ").unwrap();
        file.write_all(&16_u32.to_le_bytes()).unwrap();
        file.write_all(&1_u16.to_le_bytes()).unwrap();
        file.write_all(&1_u16.to_le_bytes()).unwrap();
        file.write_all(&sample_rate.to_le_bytes()).unwrap();
        file.write_all(&(sample_rate * 2).to_le_bytes()).unwrap();
        file.write_all(&2_u16.to_le_bytes()).unwrap();
        file.write_all(&16_u16.to_le_bytes()).unwrap();
        file.write_all(b"data").unwrap();
        file.write_all(&(samples * 2).to_le_bytes()).unwrap();
        for index in 0..samples {
            let value = if index < sample_rate {
                (12_000.
                    * (f64::from(index) / f64::from(sample_rate) * 440. * std::f64::consts::TAU)
                        .sin()) as i16
            } else {
                0
            };
            file.write_all(&value.to_le_bytes()).unwrap();
        }
        drop(file);
        let waveform = load(
            Path::new(&ffmpeg),
            &source,
            2.,
            &cache,
            &AtomicBool::new(false),
        )
        .unwrap();
        assert!(!waveform.peaks.is_empty());
        assert!(waveform.peaks.len() <= MAX_PEAKS + 1);
        let middle = waveform.peaks.len() / 2;
        assert!(waveform.peaks[..middle].iter().copied().fold(0., f32::max) > 0.2);
        let quiet_tail = middle + waveform.peaks.len() / 8;
        assert!(
            waveform.peaks[quiet_tail..]
                .iter()
                .copied()
                .fold(0., f32::max)
                < 0.001
        );
        assert_eq!(
            load(
                &temp.path().join("missing-ffmpeg"),
                &source,
                2.,
                &cache,
                &AtomicBool::new(false)
            )
            .unwrap()
            .peaks,
            waveform.peaks
        );
        fs::OpenOptions::new()
            .append(true)
            .open(&source)
            .unwrap()
            .write_all(&[0, 0])
            .unwrap();
        assert!(
            load(
                &temp.path().join("missing-ffmpeg"),
                &source,
                2.,
                &cache,
                &AtomicBool::new(false)
            )
            .is_err()
        );
        let regenerated = load(
            Path::new(&ffmpeg),
            &source,
            2.,
            &cache,
            &AtomicBool::new(false),
        )
        .unwrap();
        assert_eq!(
            load(
                &temp.path().join("missing-ffmpeg"),
                &source,
                2.,
                &cache,
                &AtomicBool::new(false)
            )
            .unwrap()
            .peaks,
            regenerated.peaks
        );
        fs::remove_file(&cache).unwrap();
        assert!(
            load(
                Path::new(&ffmpeg),
                &source,
                2.,
                &cache,
                &AtomicBool::new(true)
            )
            .is_err()
        );
    }
}
